<script setup>
import { computed, ref } from 'vue'
import { state, scenario, classified, complete, locked } from '../state.js'
import { money, percent } from '../format.js'
import ParetoChart from '../components/ParetoChart.vue'
const guide = ref(state.draft.abcGuideDone ? 3 : 0), checked = ref(null)
const rows = computed(() => guide.value >= 2 ? classified.value.rows.map(r => ({ ...scenario.value.products.find(p => p.sku === r.sku), ...r })) : scenario.value.products.map(p => ({ ...p, ...classified.value.rows.find(r => r.sku === p.sku) })))
function advance() { guide.value++; if (guide.value === 3) state.draft.abcGuideDone = true }
function choose(sku, cls) { if (locked.value || guide.value < 3) return; state.draft.abcAnswers[sku] = cls; checked.value = null }
function check() { if (locked.value || state.draft.abcChecksUsed >= scenario.value.abcCheckLimit) return; state.draft.abcChecksUsed++; checked.value = Object.fromEntries(rows.value.map(p => [p.sku, state.draft.abcAnswers[p.sku] === p.cls])) }
function keyboard(event, sku) {
  if (['a','b','c'].includes(event.key.toLowerCase())) { event.preventDefault(); choose(sku, event.key.toUpperCase()) }
  if (['ArrowUp', 'ArrowDown'].includes(event.key)) { event.preventDefault(); const list = [...event.currentTarget.parentNode.children]; list[Math.max(0,Math.min(list.length - 1,list.indexOf(event.currentTarget) + (event.key === 'ArrowDown' ? 1 : -1)))]?.focus() }
}
</script>
<template><section><div class="section-heading"><div><p class="eyebrow">STEP 02 / 按销售额认识商品</p><h1>ABC 分类</h1></div><span class="muted">已选 {{ Object.keys(state.draft.abcAnswers).length }} / {{ scenario.products.length }}</span></div><p class="rule">按销售额从高到低排列，同额按 SKU 升序。看商品<strong>加入之前</strong>的累计占比：小于 {{ percent(scenario.thresholds.a) }} 为 A；小于 {{ percent(scenario.thresholds.b) }} 为 B；其余为 C。</p><div class="actions guide"><span v-for="(label, i) in ['计算销售额', '按销售额排序', '计算累计占比']" :key="label">{{ i + 1 }} {{ label }} {{ guide > i ? '✓' : '' }}</span><button v-if="guide < 3" class="primary" :disabled="locked" @click="advance">{{ ['计算销售额', '按销售额排序', '计算累计占比'][guide] }}</button></div><div class="card table-scroll abc-table"><table><thead><tr><th>SKU</th><th>名称</th><th class="numeric">月销量</th><th class="numeric">单价</th><th v-if="guide >= 1" class="numeric">销售额</th><th v-if="guide >= 3" class="numeric">占比</th><th v-if="guide >= 3" class="numeric">加入前累计</th><th v-if="guide >= 3">分类</th></tr></thead><tbody><tr v-for="p in rows" :key="p.sku" tabindex="0" @keydown="keyboard($event, p.sku)" :class="{ incorrect: checked && !checked[p.sku] }"><td><span v-if="checked && !checked[p.sku]" class="error" aria-label="分类错误">✕ </span>{{ p.sku }}</td><td>{{ p.name }}</td><td class="numeric">{{ p.monthlySalesQty }}</td><td class="numeric">{{ money(p.unitPrice) }}</td><td v-if="guide >= 1" class="numeric">{{ money(p.salesCents / 100) }}</td><td v-if="guide >= 3" class="numeric">{{ percent(p.share) }}</td><td v-if="guide >= 3" class="numeric">{{ percent(p.cumBefore) }}</td><td v-if="guide >= 3" class="class-buttons"><button v-for="cls in ['A','B','C']" :key="cls" :class="state.draft.abcAnswers[p.sku] === cls ? 'badge-' + cls : ''" :aria-pressed="state.draft.abcAnswers[p.sku] === cls" :disabled="locked" @click="choose(p.sku, cls)">{{ cls }}</button></td></tr></tbody></table></div><div class="actions"><p class="muted small">键盘：↑ / ↓ 换行，A / B / C 选择分类。</p><span role="status" v-if="checked">正确 {{ Object.values(checked).filter(Boolean).length }} / {{ rows.length }}</span></div><ParetoChart v-if="guide >= 3" :rows="classified.rows" :answers="state.draft.abcAnswers" :thresholds="scenario.thresholds" /><footer class="page-footer"><RouterLink class="button" to="/student">← 上一步</RouterLink><div class="actions"><span>剩余检查次数：{{ Math.max(0, scenario.abcCheckLimit - state.draft.abcChecksUsed) }}</span><button :class="{ primary: guide >= 3 }" :disabled="locked || guide < 3 || state.draft.abcChecksUsed >= scenario.abcCheckLimit" @click="check">检查分类</button><RouterLink v-if="complete" class="button" to="/student/layout">下一步 →</RouterLink><button v-else disabled>请先完成分类 →</button></div></footer></section></template>
